"""New v45 physics predictions; query labels are generated by a separate process."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import sys

import numpy as np

ROOT = Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT.parent/"contact_patch_v44"))
import runner44 as old
old.BASE, old.SUPPORT_BASE = 450_000_000, 500
old.OUT = ROOT/"results"
infer, r, v38, torch = old.infer, old.r, old.v38, old.torch
DECODERS = ("original","source_axis","privileged")

def predict(panel,cell,engine,templates,selection_cache,axes,mark):
    path = old.path_for(panel,cell)
    if r.old.already_complete(path,mark):
        return
    theta,xx,sensors,_ = old.observations(panel,cell)
    fingerprint = hashlib.sha256(xx.tobytes()).digest()
    if fingerprint not in selection_cache:
        selection_cache[fingerprint] = infer.actions43(xx,engine)
    actions = selection_cache[fingerprint]
    paid = infer.paid_sensors(sensors,actions)
    shape,_,_,_,height = cell
    catalog_direction = old.world.oracle_direction(shape,height)
    generic_direction = axes[str(round(height*1000))]["axis"]
    p = []
    for decoder,u in zip(DECODERS,(None,generic_direction,catalog_direction)):
        key = (decoder,shape if decoder=="privileged" else None,height)
        if key not in templates:
            templates[key] = infer.make_template(engine,height,u)
        p.append(infer.decode43(engine,templates[key],xx,actions,paid))
    predictions = np.stack(p)[:,None]
    if not np.isfinite(predictions).all() or predictions.min()< -1e-12 or predictions.max()>1+1e-12:
        raise ValueError("Invalid probability")
    # Source / privileged predictions can differ only when a query was purchased.
    np.testing.assert_allclose(predictions[1:,0][:,actions==r.P],np.broadcast_to(predictions[0,0][actions==r.P],
                               predictions[1:,0][:,actions==r.P].shape),atol=1.e-12,rtol=0)
    path.parent.mkdir(parents=True,exist_ok=True)
    v38.atomic_npz(path,theta=theta,xx=xx,selected=actions,pred=predictions,decoders=DECODERS,policies=["zero"],
                   query_paid=np.stack([m[r.Q] for m in paid]),probe_paid=np.stack([m[r.P] for m in paid]))
    v38.atomic_json(path.with_suffix(".json"),dict(sha256=v38.digest(path),fingerprint=mark))

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("mode",choices=("even","odd","timing"))
    args=ap.parse_args()
    if not os.getenv("SLURM_JOB_ID") or not torch.cuda.is_available() or torch.cuda.device_count()!=1:
        raise RuntimeError("Expected one allocated GPU")
    torch.set_num_threads(1)
    hashes=json.loads((ROOT.parent/"blind_decoder_v43/results/run_even.json").read_text())["hashes"]
    for line in (ROOT/"gpu_freeze45.sha256").read_text().splitlines():
        val,name=line.split(maxsplit=1)
        hashes[ROOT.name+"/"+name]=val
    for name,val in hashes.items():
        if v38.digest(ROOT.parent/name)!=val:
            raise ValueError("Invalid prerequisite hash: "+name)
    mark=hashlib.sha256(json.dumps(hashes,sort_keys=True).encode()).hexdigest()
    meta=dict(job=os.environ["SLURM_JOB_ID"],fingerprint=mark,hashes=hashes,mode=args.mode,
              base=old.BASE,support_start=old.SUPPORT_BASE,device=torch.cuda.get_device_name(),
              torch=str(torch.__version__),cuda=torch.version.cuda,decoders=DECODERS)
    old.OUT.mkdir(exist_ok=True)
    v38.atomic_json(old.OUT/f"run_{args.mode}.json",meta)
    with torch.inference_mode():
        panels=range(old.PANELS) if args.mode=="timing" else range(int(args.mode=="odd"),old.PANELS,2)
        if args.mode!="timing":
            for panel in panels:old.manifest(panel)
        engine=infer.make_bank()
        axes=json.loads((ROOT/"source_axis45.json").read_text())
        templates={}
        for panel in panels:
            if args.mode=="timing":
                import timing45
                timing45.run(panel,engine,axes)
            else:
                cache={}
                order=np.random.default_rng(old.BASE+100000*panel+707).permutation(len(old.CELLS))
                for i in order:
                    predict(panel,old.CELLS[i],engine,templates,cache,axes,mark)
            print(args.mode,panel,"complete",flush=True)
    v38.atomic_json(old.OUT/f"complete_{args.mode}.json",meta)

if __name__=="__main__":
    main()
